PEER={"title":"VPC peering（AWSホワイトペーパー Amazon VPC Connectivity Options）","url":"https://docs.aws.amazon.com/whitepapers/latest/aws-vpc-connectivity-options/vpc-peering.html"}
PEERB={"title":"How VPC peering connections work（Amazon VPC ピアリングガイド）","url":"https://docs.aws.amazon.com/vpc/latest/peering/vpc-peering-basics.html"}
PEERW={"title":"What is VPC peering?（Amazon VPC ピアリングガイド）","url":"https://docs.aws.amazon.com/AmazonVPC/latest/PeeringGuide/Welcome.html"}
XVPC={"title":"Communicating across VPCs and AWS Regions（AWS Prescriptive Guidance）","url":"https://docs.aws.amazon.com/prescriptive-guidance/latest/secure-outbound-network-traffic/vpc-region-communication.html"}
PLA={"title":"Access AWS services through AWS PrivateLink（AWS PrivateLink ガイド）","url":"https://docs.aws.amazon.com/vpc/latest/privatelink/privatelink-access-aws-services.html"}
