add_terms([
 ("vpc-peering","VPCピアリング","2つのVPCを直接つなぎ、互いのプライベートIPアドレスで通信できるようにする接続です。1対1の関係で、別のVPCを経由した通信（推移的なピアリング）はできません。",
  "隣どうしの家の間に作る「専用の渡り廊下」です。A家とB家、B家とC家に廊下があっても、A家からB家を通り抜けてC家へは行けません。",
  "開発用のVPCと共有サービス用のVPCを、VPCピアリングで接続する。",[PEER,PEERB]),
 ("hub-and-spoke","ハブアンドスポーク","中央の「ハブ」に、複数の拠点（スポーク）をつなぐ構成です。拠点どうしは、ハブを経由して通信します。",
  "自転車の車輪のように、中心から放射状にのびた形です。空港の「乗り継ぎ拠点」も同じ考え方です。",
  "AWS Transit Gatewayをハブにして、多数のVPCとオンプレミスのネットワークを接続する。",[XVPC,WP]),
 ("data-lake","データレイク","あらゆるデータを、元の形のままでも、分析用に整えた形でも、1か所に集めて安全に保管しておく場所です。",
  "いろいろな川（データの発生元）から水が流れ込む「湖」のようなものです。あとで必要な水を汲んで使います。",
  "Amazon S3をデータレイクにして、AWS Lake Formationでアクセスを管理し、Amazon Athenaで分析する。",[WP,SG]),
 ("columnar-format","列指向フォーマット","データを、行ごとではなく列ごとにまとめて保存する形式です。Apache ParquetやApache ORCが代表例で、分析に向いています。",
  "名簿を「1人ずつのカード」ではなく、「名前だけの一覧」「年齢だけの一覧」に分けて持つイメージです。年齢の平均を出すとき、年齢の一覧だけを見れば済みます。",
  "Amazon Data Firehoseで、受け取ったデータをApache Parquetに変換してからAmazon S3に保存する。",[WP,SG]),
 ("cidr","CIDR","IPアドレスの範囲を表す書き方です。VPCやサブネットを作るときに、使うIPアドレスの範囲をCIDRで指定します。",
  "「この町内は1番地から256番地まで」というように、番地の範囲をまとめて表す書き方です。",
  "VPCピアリングでは、2つのVPCのIPv4のCIDRの範囲が重なっていると接続できないため、あらかじめ重ならない範囲を割り当てる。",[PEER,SG]),
])
P="saa-d3"
services=[
 ssvc(P,"aws-transit-gateway","AWS Transit Gateway",["Transit Gateway","TGW","トランジットゲートウェイ"],"networking",
  "多数のVPCとオンプレミスのネットワークを、中央のハブでつなぐサービス。",
  "各地を結ぶ「乗り継ぎ空港」です。どの都市（VPC）からも、この空港を経由すれば、ほかのすべての都市へ行けます。",
  "たくさんのVPCや社内のネットワークを、1つの中継地点にまとめてつなぐサービスです。1つずつ個別につなぐ必要がなくなります。",
  "VPCとオンプレミスのネットワークをつなぐ、中央のハブとして機能します。ハブアンドスポークのモデルで、複数のVPCとオンプレミスのネットワークを接続します。VPCの間の通信は、Transit Gatewayを通じて管理されます。VPCピアリングは推移的なルーティングに対応しないため、多数のVPCを互いに通信させたい場合は、Transit Gatewayをネットワークの中継ハブとして使えます。",
  ["多数のVPCとオンプレミスを、中央のハブでつなぐ＝AWS Transit Gateway。","ハブアンドスポークのモデル。","VPCピアリングは1対1で、推移的なルーティングができない。多数のVPCにはTransit Gateway。"],
  ["数十のVPCと、オンプレミスのネットワークを相互に接続する"],"各VPCやオンプレミスのネットワークをTransit Gatewayに接続し、Transit Gatewayが間の通信を中継します。",
  ["接続の数が増えても、構成が複雑になりにくい","オンプレミスのネットワークもつなげられる"],["2つのVPCをつなぐだけなら、VPCピアリングで足りる"],
  "VPCが増えて、VPCピアリングの接続の数が管理しきれなくなった",["aws-privatelink"],["amazon-vpc","aws-vpn","aws-direct-connect"],{"clf":"low","saa":"high"},"https://docs.aws.amazon.com/vpc/latest/tgw/",[XVPC,PEER,WP,SG]),
 ssvc(P,"aws-lake-formation","AWS Lake Formation",["Lake Formation","レイクフォーメーション"],"analytics",
  "安全なデータレイクを、短期間で簡単にセットアップできるサービス。",
  "「湖の管理事務所」です。水（データ）を集めて台帳に載せ、誰がどの水を汲んでよいかを管理します。",
  "いろいろなデータを1か所（Amazon S3）に集めて、誰がどのデータを見られるかを管理する仕組みを、簡単に作れるサービスです。",
  "安全なデータレイクを、数日で簡単にセットアップできるサービスです。データレイクは、すべてのデータを、元の形のままでも、分析用に整えた形でも保管する、一元化され、整理され、保護されたリポジトリです。Lake Formationは、データを収集してカタログ化し、Amazon S3のデータレイクに移し、機密性の高いデータへのアクセスを保護します。",
  ["安全なデータレイクの構築とアクセス管理＝AWS Lake Formation。","データレイクの保存先はAmazon S3。","データの変換（ETL）はAWS Glue、SQLでの分析はAmazon Athena。"],
  ["複数のシステムのデータを集めた、分析用のデータレイクの構築"],"データを収集してカタログ化し、S3のデータレイクに移して、アクセスを管理します。",
  ["データレイクの構築が短期間で済む","アクセスの管理を一元化できる"],["データの分析そのものは、AthenaやRedshiftなどで行う"],
  "部署ごとに見せるデータを分けながら、全社のデータをS3に集める",["aws-glue"],["amazon-s3","aws-glue","amazon-athena"],{"clf":"low","saa":"mid"},"https://docs.aws.amazon.com/lake-formation/",[WP,SG]),
 ssvc(P,"amazon-data-firehose","Amazon Data Firehose",["Data Firehose","Firehose","Kinesis Data Firehose","ファイアホース"],"analytics",
  "ストリーミングデータを、データストアや分析ツールに確実に読み込ませる、フルマネージドのサービス。",
  "流れてくる水を、決まった貯水池まで運ぶ「送水管」です。途中でろ過（変換）もできます。",
  "次々に流れてくるデータを受け取って、Amazon S3などの保存先まで自動で届けてくれるサービスです。",
  "ストリーミングデータを、データストアや分析ツールに確実に読み込ませるための、最も簡単な方法です。ストリーミングデータを取り込み、変換して、Amazon S3、Amazon Redshift、Amazon OpenSearch Service、Splunkに読み込ませます。フルマネージドで、データのスループットに合わせて自動的にスケールし、継続的な管理は不要です。Amazon S3に届ける前に、受け取ったデータをApache ParquetやApache ORCといった列指向のフォーマットに変換することもできます。",
  ["ストリーミングデータを保存先（S3、Redshiftなど）へ届ける＝Amazon Data Firehose。","自動でスケールし、管理が不要。","S3に届ける前に、ParquetやORCに変換できる。","ミリ秒単位でデータを使うリアルタイムの処理はAmazon Kinesis Data Streams。"],
  ["アプリのログを、継続的にS3へ保存する"],"データを受け取り、必要なら変換して、指定した保存先に届けます。",
  ["保存先までの配信を自分で作らなくてよい","自動でスケールする"],["独自のリアルタイム処理を作り込む用途にはKinesis Data Streamsが合う"],
  "クリックの記録をParquetに変換しながらS3にため、Athenaで分析する",["amazon-kinesis"],["amazon-s3","amazon-redshift","amazon-athena"],{"clf":"low","saa":"high"},"https://docs.aws.amazon.com/firehose/",[WP,SG]),
 ssvc(P,"aws-snow-family","AWS Snow Family",["Snow Family","Snowball","Snowball Edge","スノーファミリー"],"migration-transfer",
  "ネットワークでは運びにくい大量のデータを、物理的な機器でAWSとの間で運ぶサービス。",
  "データの「引っ越しトラック」です。回線で送ると何か月もかかる荷物を、箱に詰めて物理的に運びます。",
  "専用の機器にデータを入れて、その機器ごとAWSに送ることで、大量のデータを運ぶサービスです。ネットワークが使えない場所でも使えます。",
  "過酷な、データセンターではない環境や、安定したネットワーク接続がない場所で運用する必要がある顧客を支援します。AWS SnowballとAWS Snowball Edgeで構成され、多くはコンピューティングの機能を内蔵した、いくつかの物理的な機器を提供します。エクサバイト規模までのデータを、AWSとの間で物理的に輸送するのに役立ちます。",
  ["大量のデータを物理的な機器で輸送＝AWS Snow Family。","安定したネットワーク接続がない場所でも使える。コンピューティングの機能を内蔵した機器もある。","ネットワーク経由のデータ移動はAWS DataSync。"],
  ["回線が細い拠点から、大量のデータをAWSへ移す"],"機器にデータを入れ、機器をAWSに送ることで、データを移します。",
  ["ネットワークに頼らずに大量のデータを運べる"],["機器の輸送の時間がかかる"],
  "ネットワークで送ると数か月かかる量のデータを、AWSへ移す",["aws-datasync"],["amazon-s3"],{"clf":"low","saa":"mid"},"https://docs.aws.amazon.com/snowball/",[WP,SG]),
 ssvc(P,"amazon-opensearch-service","Amazon OpenSearch Service",["OpenSearch Service","OpenSearch","オープンサーチ"],"analytics",
  "OpenSearchを使って、データをリアルタイムに検索、分析、可視化できるようにするサービス。",
  "膨大な書類の中から、キーワードで一瞬にして探し出す「検索係」です。",
  "大量のログや文章の中から、キーワードで素早く検索したり、傾向を可視化したりするためのサービスです。",
  "OpenSearchを簡単にデプロイ、保護、運用、スケールして、データをリアルタイムに検索、分析、可視化できるようにします。ログ分析、全文検索、アプリケーションの監視、クリックストリーム分析などの用途に向いています。",
  ["ログ分析・全文検索＝Amazon OpenSearch Service。","リアルタイムに検索、分析、可視化する。","S3のデータへのSQLはAmazon Athena、データウェアハウスはAmazon Redshift。"],
  ["アプリケーションのログの検索と可視化","サイト内の全文検索"],"データを取り込み、検索や分析のリクエストに応えます。",
  ["キーワードでの検索が速い","運用をAWSに任せられる"],["業務データの複雑な集計にはデータウェアハウスが合う"],
  "大量のログから、エラーの発生状況をキーワードで検索する",["amazon-athena"],["amazon-data-firehose","amazon-cloudwatch"],{"clf":"low","saa":"mid"},"https://docs.aws.amazon.com/opensearch-service/",[WP,SG]),
]
for x in services: w(f"services/{x['id']}.json",x)
